-- Gold Query
SELECT t2.chanceCreationPassing, t2.chanceCreationPassingClass FROM Team AS t1 INNER JOIN Team_Attributes AS t2 ON t1.team_api_id = t2.team_api_id WHERE t1.team_long_name = 'Ajax' ORDER BY t2.chanceCreationPassing DESC, t1.id NULLS LAST, t2.id NULLS LAST LIMIT 1;

/*
Gold Result:
(2, 'default2')
*/

-- Prediction Query
SELECT MAX(ta.chanceCreationPassing) AS max_chance_creation_passing, ta.chanceCreationPassingClass FROM Team_Attributes AS ta JOIN Team AS t ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'Ajax' GROUP BY ta.chanceCreationPassingClass ORDER BY max_chance_creation_passing DESC, ta.chanceCreationPassingClass NULLS LAST LIMIT 1;

/*
Prediction Result:
(2, 'Ajax')
